pub fn quadSamplerSlot(smp_name: []const u8) ?usize {
    _ = smp_name;
    return null;
}
pub fn quadUniformblockSlot(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "xvalues")) {
        return 0;
    }
    if (std.mem.eql(u8, ub_name, "yvalues")) {
        return 1;
    }
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        return 2;
    }
    return null;
}
pub fn quadUniformblockSize(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "xvalues")) {
        return @sizeOf(Xvalues);
    }
    if (std.mem.eql(u8, ub_name, "yvalues")) {
        return @sizeOf(Yvalues);
    }
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        return @sizeOf(VsParams);
    }
    return null;
}
pub fn quadUniformOffset(ub_name: []const u8, u_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "xvalues")) {
        if (std.mem.eql(u8, u_name, "x_values")) {
            return 0;
        }
    }
    if (std.mem.eql(u8, ub_name, "yvalues")) {
        if (std.mem.eql(u8, u_name, "y_values")) {
            return 0;
        }
    }
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "zoom")) {
            return 0;
        }
        if (std.mem.eql(u8, u_name, "window_scale")) {
            return 64;
        }
        if (std.mem.eql(u8, u_name, "untransform")) {
            return 128;
        }
    }
    return null;
}
pub fn quadUniformDesc(ub_name: []const u8, u_name: []const u8) ?sg.GlslShaderUniform {
    if (std.mem.eql(u8, ub_name, "xvalues")) {
        if (std.mem.eql(u8, u_name, "x_values")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT4;
            desc.array_count = 1000;
            desc.glsl_name = "x_values";
            return desc;
        }
    }
    if (std.mem.eql(u8, ub_name, "yvalues")) {
        if (std.mem.eql(u8, u_name, "y_values")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT4;
            desc.array_count = 1000;
            desc.glsl_name = "y_values";
            return desc;
        }
    }
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "zoom")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "zoom";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "window_scale")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "window_scale";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "untransform")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "untransform";
            return desc;
        }
    }
    return null;
}
